import{_ as e,o as t,c as a,a4 as r}from"./chunks/framework.C3unmAF4.js";const c=JSON.parse('{"title":"“AI+农业”：如何从“云”上落到“地”里","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"“AI+农业”：如何从“云”上落到“地”里","date":"2026-08-03T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202607/t20260720_6485912.htm","summary":"温室里，喷雾机器人沿轨道滑行，雾化药滴随风贴上叶背，害虫无处可逃；牛舍中，“牛脸识别”紧盯每头牛的健康，实时向云端传送数据；蓝莓棚内，AI算法值守，缺水、缺肥、忘关风口时，系统立刻报警……\\n人工智能正深度融入农田。2026年中央一号文件明确，因地制宜发展农业新质生产力，促进人工智能与农业发展相结合。政策东风已至，AI能否真正“带飞”农业？\\n从“会养”“会种”到“慧养”“慧种”\\n...\\n","contentHash":"5e428840009fdfe0ad2966b1d63a904d","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-08-03-AI-农业-如何从-云-上落到-地-里.md","filePath":"news/2026-08-03-AI-农业-如何从-云-上落到-地-里.md"}'),_={name:"news/2026-08-03-AI-农业-如何从-云-上落到-地-里.md"};function n(s,p,o,l,d,A){return t(),a("div",null,[...p[0]||(p[0]=[r('<h1 id="ai-农业-如何从-云-上落到-地-里" tabindex="-1">“AI+农业”：如何从“云”上落到“地”里 <a class="header-anchor" href="#ai-农业-如何从-云-上落到-地-里" aria-label="Permalink to &quot;“AI+农业”：如何从“云”上落到“地”里&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202607/t20260720_6485912.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-08-03 摘要: 温室里，喷雾机器人沿轨道滑行，雾化药滴随风贴上叶背，害虫无处可逃；牛舍中，“牛脸识别”紧盯每头牛的健康，实时向云端传送数据；蓝莓棚内，AI算法值守，缺水、缺肥、忘关风口时，系统立刻报警…… 人工智能正深度融入农田。2026年中央一号文件明确，因地制宜发展农业新质生产力，促进人工智能与农业发展相结合。政策东风已至，AI能否真正“带飞”农业？ 从“会养”“会种”到“慧养”“慧种” ...</p></blockquote><p>人工智能正深度融入农田。2026年中央一号文件明确，因地制宜发展农业新质生产力，促进人工智能与农业发展相结合。政策东风已至，AI能否真正“带飞”农业？</p><p>从“会养”“会种”到“慧养”“慧种”</p><p>内蒙古和林格尔县的蒙牛嘉立荷生态牧场，和江苏连云港的东旺奶牛养殖基地，正运行着同一套“牛脸识别”系统。无需近距离拍摄，后台屏幕动态框出牛脸，饮食、健康、行为数据一目了然。</p><p>“这不是保险理赔用的识别工具，而是智慧养殖工具。”系统研发方寿光市翔天农业科技有限公司副总经理刘守城说。每头牛都有“数字身份证”，全天候“点名”，可实现精确投喂。养殖数据直传农业、防疫部门，食品安全可追溯。试点以来，已覆盖超7000头牛，饲料利用率提升25%，发病率降低20%。</p><p>京津冀的果蔬棚里，AI也在“护航”。</p><p>在河北卢龙县采葑农业基地，78座高标准智能温室连片排布。“我们全程按照有机标准种植蓝莓，养分供给、田间管理每一环都要求精细。没有AI智能设备辅助，想要稳定把控产量与果品品质难度很大。”基地负责人陈磊说。</p><p>大棚里，传感器无处不在。温度到了，风口自动开启；缺水、缺肥、设备故障时，系统立刻报警。过去70多个棚要二三十人管理，一人最多看两三个；现在4到5人管全部，日常巡查就行。</p><p>冷雾机、采摘机器人、蔬菜园艺机器人、生态氢水农业数字化大型机械装置……第二十七届中国（寿光）国际蔬菜科技博览会上，智慧化设备扎堆亮相。潍坊科技学院“马家兴工匠人才创新工作室”研发并展示的多款智慧农业机器人中，一款自动栽苗机器人引人注目。</p><p>第二十七届中国（寿光）国际蔬菜科技博览会上展示的栽苗机器人（4月20日摄）。新华社记者 徐速绘 摄</p><p>“取苗、栽苗、埋土，全是累活。”潍坊科技学院人工智能学院副院长马家兴说，“我们给它装了高精度视觉系统，能挑健康苗，柔性移栽不伤根，解决了人工慢、伤苗多、标准乱的问题，帮设施农业往规模化、标准化走。”</p><p>从温室物联到AI决策，从单台设备到全栈方案，“慧养”“慧种”的图景正在各地铺开。智研咨询数据显示，2017年到2025年，中国智慧农业行业市场规模从384.74亿元增至1200亿元，年复合增长率15.28%。</p><p>从“技术账”到“经济账”</p><p>AI可以赋能农业，但普通农户能不能用得起、用得好？</p><p>河北科技师范学院数学与信息科技学院博士陈基亮说，一套AI系统，传感终端、边缘计算、决策模型全算上，初始投入比较大。</p><p>多名受访者反映，一个具备完整环境数据采集能力、AI操作系统，能够适应极端气候的“种植集装箱”，单个售价在20万元至30万元；在不包括地租、水电、种苗等投入的前提下，一个配套有物联网系统、传感器和智能灌溉、植保等的智慧大棚，建设成本在每平方米300元至1500元，不同地区价格有所浮动。</p><p>短板不止在钱，更在人。</p><p>“村里种庄稼大多靠老人，他们还是习惯按传统方式耕作。”华北地区的一名合作社负责人告诉记者，他所在的村子，村里40岁以下年轻人只有50人左右，不足全村总人数6%。</p><p>中国农业大学信息与电气工程学院副教授李想说，目前农业经营主力仍是中老年群体，数字化操作和维护能力不足；下沉到村懂技术、懂农业的青年人才极为短缺，不少地方出现“设备买回来，说明书看不懂”的情况。</p><p>地形和数据也“卡脖子”。</p><p>我国山区丘陵多，作物种类杂，小农经营仍占大头。河北科技师范学院二级教授张立彬认为，智慧农业在平原容易实现，但平原验证过的算法，搬到山地丘陵未必好使。</p><p>“数据以及配套的算法和智能装备，是行业更深层次的挑战。”山东农业大学农学院副教授陈国庆说，农业生产周期长、环境复杂、区域差异大，高质量农业数据不足，制约了AI模型训练迭代；许多农业AI应用仍停留在监测、识别和预警阶段，能直接服务精准决策和自主作业的核心技术有待突破。</p><p>这是在第二十七届中国（寿光）国际蔬菜科技博览会上展示的农业用途机器人（4月20日摄）。新华社记者 徐速绘 摄</p><p>从“技术盆景”到“产业风景”</p><p>破局已在路上。</p><p>寿光农控集团的“智慧农业全栈示范区”里，有一套“AI机器人+银发专家”协同作业体系。传统农技服务依赖个人经验和体能，而“AI机器人+银发专家”将40年“寿光模式”经验提炼为数智化内核，技术服务效率提升5倍以上。</p><p>巡检蔬菜的机器狗，也装着“农事大脑”。“里面植入的农业大模型，把寿光40年种植经验变成数字指令。”寿光农控智慧农业展区现场工作人员王怡红说。</p><p>从“技术盆景”落地为“产业风景”，业内专家发现，“让技术找人”比“让人学技术”更易于实现。</p><p>李想说，要求患者直接读懂CT、B超报告很难，但医生能看懂并据此服务患者。同理，AI设备和算法的结果，应该交给农业技术人员、服务人员、农资销售人员，让他们更好地服务农民。农户只需知道“今天该浇多少水”“这片叶子该打什么药”，不必费心理解农业大模型如何训练。</p><p>陈基亮建议，应依托农技推广体系、社会化服务组织或第三方团队，将AI封装为“即用型服务”，引导青年技术人才下乡，负责安装、校准、维护，依据农时节点提供简明建议。</p><p>农业农村部关于落实《中共中央 国务院关于锚定农业农村现代化扎实推进乡村全面振兴的意见》的实施意见提出，大力推进智慧农业行动计划，拓展无人机、物联网、机器人等应用场景，支持有条件的地区在智慧农业建设上先行先试，培育一批智慧农（牧、渔）场。</p><p>陈国庆认为，未来农业AI的发展方向，是将农业机理模型、人工智能算法与智能装备拧成一股绳，构建“感知—决策—执行”闭环体系，实现从数据分析向生产力提升转变，真正推动农业生产方式变革。“解决了普通农户用得起、用得会、用得值的问题，‘AI+农业’才算真正从‘云’上落到了‘地’里。”（记者叶婧、郭雅茹）</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202607/t20260720_6485912.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',34)])])}const i=e(_,[["render",n]]);export{c as __pageData,i as default};
